MATCH (source:PlantItem {tag: 'P-44001A'})
MATCH (v:Valve), (e:Equipment)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (e:Equipment {tag: 'E-31402'})-[:measured_by]->(i:ProcessInstrumentationFunction)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'TI-134065'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'TK-32302'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-53401'}), (b:PlantItem {tag: 'V-53401'}), (v:Valve)
WHERE v <> b
  AND EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (equipment:Equipment)-[:measured_by]->(sensor:ProcessInstrumentationFunction {loop_tag: 'TI-497041'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-37201A'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(:ProcessInstrumentationFunction {loop_tag: 'CI-41006'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'LALL-380024'})
MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE sensor.loop_tag = head.loop_tag
  AND EXISTS { (sensor)-[:send_signal_to*1..]->(head) }
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'P-41601B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-56801A'}), (b:PlantItem {tag: 'P-56901A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'CHV-568001' AND y.tag <> 'CHV-568001')+ (b)
       } AS reachable

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem),
      (sensor)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'TIAH-18019'})
RETURN DISTINCT equipment.tag AS tag ORDER BY tag;

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-3701'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (loop:PlantItem:ProcessInstrumentationFunction {loop_tag: 'CSHH-396019'})-[:send_signal_to*1..]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(loop:ProcessInstrumentationFunction {tag: 'PI-4063'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (h:PlantItem {tag: 'H-46101'}), (e:PlantItem {tag: 'E-46101'}), (v:Valve)
WHERE EXISTS { (h)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (pump:PlantItem {tag: 'P-38001A'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (pump:PlantItem {tag: 'P-38001A'})
MATCH (pump)-[:line_to*1..]->(v:Valve)
WHERE NOT EXISTS {
  MATCH (pump)-[:line_to*1..]->(e:Equipment)
  WHERE e <> v
    AND EXISTS { (pump)-[:line_to*1..]->(e) }
    AND NOT EXISTS {
      MATCH (pump)-[:line_to*1..]->(v2:PlantItem)
      WHERE v2 <> v
    }
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem {tag: 'V-14401'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'R-26101'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'E-32101'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem:CentrifugalPump {unit_id: '83'})
RETURN p.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-50801A'}), (b:PlantItem {tag: 'P-50901A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (s:PlantItem {tag: 'T-32601'}), (t:PlantItem {tag: 'P-32602C'}), (v:Valve)
WHERE EXISTS { (s)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(t) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'EA-5901'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT i.tag AS tag, s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'D-37201'}), (b:PlantItem {tag: 'TK-37303'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag
